args.code:
const ctx = await tool.tabs_context({ _: "" });
console.log("Current tabs in group:", JSON.stringify(ctx.pages, null, 2));

// On 1Password pricing tab, let's make sure the Personal view is selected
const opPriceTab = ctx.pages.find(p => p.url.includes("1password.com/pricing"));
if (opPriceTab) {
  // Let's click the Personal tab if present
  try {
    const clicked = await browserjs(opPriceTab.tabId, () => {
      const personalLink = Array.from(document.querySelectorAll('a, button')).find(el => el.textContent.trim() === 'Personal');
      if (personalLink) {
        personalLink.click();
        return "Clicked Personal link";
      }
      return "Personal link not found";
    });
    console.log("1Password interaction:", clicked);
  } catch (e) {
    console.log("1Password click error:", e.message);
  }
}

